	struct iphdr *ip = data + sizeof(*eth);
	if (data + sizeof(*eth) + sizeof(*ip) > data_end)
		return XDP_PASS;

	/* Only process IPv4 traffic */
	if (ip->version != 4)
		return XDP_PASS;

	/* Verify TCP header bounds */
