	if (!(tcp->syn))
		return XDP_PASS;

	/* Extract /24 subnet from source IP (lower 24 bits) */
	__u32 subnet = ip->saddr & 0x00FFFFFF;

	/* Lookup current SYN count for this subnet */
	__u32 *count = bpf_map_lookup_elem(syn_subnet_map, &subnet);
	if (count) {
